VideoCapture.example:
#include <opencv2/opencv.hpp>
#include <iostream>

int main() {
  cv::VideoCapture cap(0);  // 0 = default camera
  if (!cap.isOpened()) {
    std::cerr << "Cannot open camera" << std::endl;
    return 1;
  }
  cv::Mat frame;
  while (cap.read(frame)) {
    cv::imshow("camera", frame);
    if (cv::waitKey(1) == 27) break;  // Esc quits
  }
  return 0;
}

