VideoWriter.example:
#include <opencv2/opencv.hpp>
#include <iostream>

int main() {
  cv::VideoWriter writer("out.avi", cv::VideoWriter::fourcc('M', 'J', 'P', 'G'), 30.0, cv::Size(640, 480));
  if (!writer.isOpened()) return 1;
  cv::Mat frame(480, 640, CV_8UC3, cv::Scalar(0, 0, 0));
  for (int i = 0; i < 90; ++i) writer.write(frame);  // three seconds at 30 fps
  writer.release();
  return 0;
}

